import os
import sqlite3

db_dir = r"C:\Users\66830\.gemini\antigravity\conversations"
for filename in os.listdir(db_dir):
    if filename.endswith(".db"):
        db_path = os.path.join(db_dir, filename)
        try:
            conn = sqlite3.connect(db_path)
            cursor = conn.cursor()
            # Find tables
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
            tables = [row[0] for row in cursor.fetchall()]

            # Search tables for "Migrating Smart Investment"
            for table in tables:
                try:
                    cursor.execute(f"PRAGMA table_info({table});")
                    columns = [row[1] for row in cursor.fetchall()]
                    for col in columns:
                        cursor.execute(f"SELECT COUNT(*) FROM {table} WHERE {col} LIKE ?;", ("%Smart Investment%",))
                        count = cursor.fetchone()[0]
                        if count > 0:
                            print(f"Found in {filename} -> table {table}, column {col}: {count} rows")
                except Exception as e:
                    pass
            conn.close()
        except Exception as e:
            print(f"Error reading {filename}: {e}")

