$transcriptPath = "C:\Users\66830\.gemini\antigravity\brain\f43ccb5d-807c-497e-8d6d-b3d8563d9ba8\.system_generated\logs\transcript.jsonl"
$outputPath = "C:\Users\66830\.gemini\antigravity\scratch\migrating_smart_investment_history.md"

$lines = Get-Content -Path $transcriptPath -Encoding UTF8
$markdown = @()

$markdown += "# Conversation History: Migrating Smart Investment"
$markdown += ""

$turnCount = 1

foreach ($line in $lines) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    try {
        $obj = ConvertFrom-Json $line -ErrorAction Stop
    } catch {
        continue
    }

    if ($obj.type -eq "USER_INPUT") {
        $content = $obj.content
        $cleanContent = $content
        if ($content -match "<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>") {
            $cleanContent = $Matches[1].Trim()
        }

        $markdown += "## User Turn $turnCount"
        $markdown += $cleanContent
        $markdown += ""
        $markdown += "---"
        $markdown += ""
    } elseif ($obj.type -eq "PLANNER_RESPONSE" -and $obj.content) {
        $content = $obj.content.Trim()
        if ($content) {
            $markdown += "## AI Turn $turnCount"
            $markdown += $content
            $markdown += ""
            $markdown += "---"
            $markdown += ""
            $turnCount++
        }
    }
}

$markdown | Out-File -FilePath $outputPath -Encoding utf8
Write-Output "Done"

# Search for our conversation ID in config files
$searchDir = "C:\Users\66830\.gemini"
Get-ChildItem -Path $searchDir -Filter "*.json" -Recurse | ForEach-Object {
    $content = Get-Content -Path $_.FullName -Raw
    if ($content -like "*c74aae43-d550-455a-9839-b6e8603c874e*") {
