}

# Search for files with the word "investment" under config
Get-ChildItem -Path "C:\Users\66830\.gemini" -Recurse -File | ForEach-Object {
    $name = $_.FullName
    if ($name -like "*scratch*" -or $name -like "*brain*") { continue }
    try {
        $content = Get-Content -Path $name -Raw -ErrorAction Ignore
        if ($content -and $content -like "*investment*") {
            Write-Output "Found in: $name"
        }
    } catch {}
}

